def solve(inp):
    h,w=len(inp),len(inp[0])
    seen=[[False]*w for _ in range(h)]; objs=[]
    for r in range(h):
        for c in range(w):
            if inp[r][c] not in (0,2) and not seen[r][c]:
                col=inp[r][c]; stack=[(r,c)]; cells=[]; seen[r][c]=True
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and inp[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                objs.append((min(y for y,x in cells),cells))
    objs.sort(key=lambda o:o[0])
    out=[[0]*w for _ in range(h)]; out[0]=[2]*w
    for top,cells in objs:
        for t in range(1,h):
            if all(out[t+y-top][x]==0 and t+y-top>=1 and t+y-top<h for y,x in cells):
                for y,x in cells: out[t+y-top][x]=inp[y][x]
                break
    return out
def solve_left(inp):
    o=solve([list(r) for r in zip(*inp)])
    return [list(r) for r in zip(*o)]
