def flip(g): return [list(r) for r in g[::-1]]
def solve_towards_bar(inp):
    h=len(inp)
    # find bar: full row or column of 2s
    if all(v==2 for v in inp[0]): return solve(inp)
    if all(v==2 for v in inp[-1]): return flip(solve(flip(inp)))
    if all(r[0]==2 for r in inp): return [list(r) for r in zip(*solve([list(r) for r in zip(*inp)]))]
    if all(r[-1]==2 for r in inp): return [list(r) for r in zip(*flip(solve(flip([list(r) for r in zip(*inp)]))))]
